-- One slot. Draft only.
BEGIN;
-- PT118-S3-Q6
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND q.stimulus=$batch01$Editorial: The premier’s economic advisor assures her that with the elimination of wasteful spending the goal of reducing taxes while not significantly decreasing government services can be met. But the premier should not listen to this advisor, who in his youth was convicted of embezzlement. Surely his economic advice is as untrustworthy as he is himself, and so the premier should discard any hope of reducing taxes without a significant decrease in government services.$batch01$ AND q.prompt=$batch01$Which one of the following is a questionable argumentative strategy employed in the editorial's argument?$batch01$ AND q.correct_choice=$batch01$C$batch01$) THEN RAISE EXCEPTION 'Question changed: PT118-S3-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S3-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$rejecting a proposal on the grounds that a particular implementation of the proposal is likely to fail$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT118-S3-Q6 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$trying to win support for a proposal by playing on people’s fears of what could happen otherwise$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT118-S3-Q6 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$criticizing the source of a claim rather than examining the claim itself$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT118-S3-Q6 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$taking lack of evidence for a claim as evidence undermining that claim$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT118-S3-Q6 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$presupposing what it sets out to establish$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT118-S3-Q6 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT118-S3-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$The premier should reject the advisor's recommendation and abandon hope of cutting taxes without a significant service reduction.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$The advisor was convicted of embezzlement in his youth, so his economic advice is allegedly untrustworthy.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$A past conviction may justify scrutinizing the person, but it says little about the specific economic prediction. Wasteful spending might be large enough to cut without reducing services. The editorial offers no calculation or policy evidence to test that claim. Rejecting the source leaves the substance unresolved.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Identify the attack on the claimant in place of an examination of the claim.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The editorial does not analyze a particular implementation of spending cuts and predict its failure. It dismisses the proposal by invoking the advisor's past.$batch01$), ($batch01$B$batch01$, $batch01$The editorial is not promoting an alternative proposal by stoking fear of its rejection. It is arguing against the advisor's proposal.$batch01$), ($batch01$C$batch01$, $batch01$The source's youthful embezzlement conviction is used to discredit the present economic claim. Whether wasteful spending can be eliminated sufficiently requires evidence about budgets and services, which the editorial does not examine.$batch01$), ($batch01$D$batch01$, $batch01$The writer does not merely say there is no evidence for the advisor's claim. He offers a personal reason to distrust the advisor, then treats that as grounds to reject the claim.$batch01$), ($batch01$E$batch01$, $batch01$The premise about a conviction does not restate the conclusion about tax cuts and services. The reasoning is flawed, but it is not circular.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT118-S3-Q6$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
